@layer components {
  :where([data-control-family="empty"][data-slot="root"]) {
    --empty-radius: var(--radius-lg);
    --empty-background: transparent;
    --empty-border-color: transparent;
    --empty-border-width: 0px;
    --empty-border-style: solid;
    --empty-media-radius: var(--radius-lg);
    --empty-media-background: var(--muted);
    border: var(--empty-border-width) var(--empty-border-style)
      var(--empty-border-color);
    border-radius: var(--empty-radius);
    background: var(--empty-background);
    box-shadow: none;
    color: var(--foreground);
  }

  :where([data-control-family="empty"][data-slot="media"]) {
    border-radius: var(--empty-media-radius);
    background: var(--empty-media-background);
    color: var(--muted-foreground);
  }

  :where([data-control-family="empty"][data-slot="content"]) {
    font-size: var(--text-sm);
    line-height: var(--text-sm--line-height);
    --_empty-content-text-wrap: balance;
    text-wrap: var(--_empty-content-text-wrap);
  }

  :where([data-control-family="empty"][data-slot="description"]) {
    font-size: var(--text-sm);
    line-height: var(--leading-relaxed);
    color: var(--muted-foreground);
  }

  :where([data-control-family="empty"][data-slot="title"]) {
    font-size: var(--text-sm);
    line-height: var(--text-sm--line-height);
    font-weight: var(--font-weight-medium);
    color: var(--foreground);
  }

  :where([data-control-family="empty"][data-slot="header"]) {
    --_empty-header-text-align: center;
    text-align: var(--_empty-header-text-align);
  }

  :where([data-control-family="empty"][data-slot="root"]) {
    --_empty-root-text-align: center;
    text-align: var(--_empty-root-text-align);
    --_empty-root-text-wrap: balance;
    text-wrap: var(--_empty-root-text-wrap);
  }
}

@property --empty-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --empty-background {
  syntax: "*";
  inherits: true;
  initial-value: transparent;
}

@property --empty-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --empty-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --empty-border-style {
  syntax: "*";
  inherits: true;
  initial-value: solid;
}

@property --empty-media-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --empty-media-background {
  syntax: "*";
  inherits: true;
  initial-value: transparent;
}

import type { ComponentProps, CSSProperties } from "react";
import type {
  EmptyContentProps,
  EmptyDescriptionProps,
  EmptyMediaProps,
  EmptyProps,
  EmptyTitleProps,
} from "@/components/control-ui/contracts";
import type { EmptyKnobStyle } from "@/components/control-ui/knob-contracts";
import { cn } from "@/components/control-ui/lib/cn";

export function Empty({ className, ...props }: EmptyProps) {
  return (
    <div
      data-control-ui="empty"
      data-control-family="empty"
      data-slot="root"
      className={cn("flex min-w-0 flex-1 flex-col items-center justify-center gap-6 p-6", className)}
      {...props}
    />
  );
}

export function EmptyHeader({ className, ...props }: ComponentProps<"div"> & { style?: CSSProperties & EmptyKnobStyle }) {
  return (
    <div
      data-control-ui="empty"
      data-control-family="empty"
      data-slot="header"
      className={cn("flex max-w-sm flex-col items-center gap-2", className)}
      {...props}
    />
  );
}

export function EmptyMedia({ className, ...props }: EmptyMediaProps) {
  return (
    <div
      data-control-ui="empty"
      data-control-family="empty"
      data-slot="media"
      className={cn("mb-2 flex size-10 shrink-0 items-center justify-center [&>svg]:size-5 [&>svg]:shrink-0", className)}
      {...props}
    />
  );
}

export function EmptyTitle({ className, ...props }: EmptyTitleProps) {
  return <div data-control-ui="empty" data-control-family="empty" data-slot="title" className={className} {...props} />;
}

export function EmptyDescription({ className, ...props }: EmptyDescriptionProps) {
  return <p data-control-ui="empty" data-control-family="empty" data-slot="description" className={className} {...props} />;
}

export function EmptyContent({ className, ...props }: EmptyContentProps) {
  return (
    <div
      data-control-ui="empty"
      data-control-family="empty"
      data-slot="content"
      className={cn("flex w-full max-w-sm flex-col items-center justify-center gap-2", className)}
      {...props}
    />
  );
}
